<?php get_header();$activities=new WP_Query(array('post_type'=>'gmr_event','post_status'=>'publish','posts_per_page'=>12,'tax_query'=>array(array('taxonomy'=>'gmr_event_type','field'=>'slug','terms'=>array('actividad','taller','conversatorio'))),'meta_key'=>'gmr_event_start','orderby'=>'meta_value','order'=>'ASC','meta_query'=>array(gmr_theme_visibility_meta_query())));?><header class="gmr-archive-head"><div class="gmr-wrap"><span class="gmr-kicker">Aprendizaje y encuentro</span><h1 class="gmr-page-title">Actividades</h1><p>Talleres, conversaciones y experiencias para acercarse al arte y sus creadores.</p></div></header><section class="gmr-section"><div class="gmr-wrap gmr-editorial-grid"><?php if($activities->have_posts()):while($activities->have_posts()):$activities->the_post();get_template_part('template-parts/story','card');endwhile;else:?><p class="gmr-empty">Pronto anunciaremos nuevas actividades.</p><?php endif;wp_reset_postdata();?></div></section><?php get_footer();?>
